<script setup>
import { computed, onMounted, ref } from "vue";
import DashboardLayout from "../../layouts/DashboardLayout.vue";
import { getMembers } from "../../services/member.service.js";
import { createMeeting, deleteMeeting, getMeetings, updateMeeting } from "../../services/meeting.service.js";
import { useAuthStore } from "../../stores/auth.store.js";

const authStore = useAuthStore();
const meetings = ref([]); const members = ref([]); const loading = ref(false); const saving = ref(false);
const errorMessage = ref(""); const showForm = ref(false); const showDelete = ref(false); const editingId = ref(null); const selectedMeeting = ref(null);
const form = ref({ meeting_date: "", agenda: "", decisions: "", status: "scheduled", attendance: [] });
const canManage = computed(() => ["admin", "chairperson", "secretary"].includes(authStore.user?.role));
const currency = (value) => new Intl.NumberFormat("en-TZ", { style: "currency", currency: "TZS", maximumFractionDigits: 0 }).format(value || 0);
const totalContributions = computed(() => meetings.value.reduce((sum, meeting) => sum + Number(meeting.contributions_collected), 0));
const completedCount = computed(() => meetings.value.filter((meeting) => meeting.status === "completed").length);
const averageAttendance = computed(() => {
  const tracked = meetings.value.reduce((sum, meeting) => sum + Number(meeting.attendance_count), 0);
  const attended = meetings.value.reduce((sum, meeting) => sum + Number(meeting.present_count) + Number(meeting.late_count), 0);
  return tracked ? Math.round((attended / tracked) * 100) : 0;
});
const attendanceSummary = computed(() => form.value.attendance.reduce((summary, entry) => { summary[entry.attendance_status]++; summary.contributions += Number(entry.contribution_amount || 0); summary.penalties += Number(entry.penalty_amount || 0); return summary; }, { present: 0, late: 0, absent: 0, excused: 0, contributions: 0, penalties: 0 }));

const blankAttendance = () => members.value.map((member) => ({ member_id: member.id, first_name: member.first_name, last_name: member.last_name, attendance_status: "absent", contribution_amount: 0, penalty_amount: 0, penalty_reason: "Missed meeting", notes: "" }));
const openCreate = () => { editingId.value = null; form.value = { meeting_date: "", agenda: "", decisions: "", status: "scheduled", attendance: blankAttendance() }; errorMessage.value = ""; showForm.value = true; };
const openEdit = (meeting) => {
  editingId.value = meeting.id;
  const attendanceMap = new Map(meeting.attendance.map((item) => [Number(item.member_id), item]));
  form.value = { meeting_date: new Date(meeting.meeting_date).toISOString().slice(0, 16), agenda: meeting.agenda, decisions: meeting.decisions || "", status: meeting.status, attendance: members.value.map((member) => ({ member_id: member.id, first_name: member.first_name, last_name: member.last_name, attendance_status: attendanceMap.get(Number(member.id))?.attendance_status || "absent", contribution_amount: attendanceMap.get(Number(member.id))?.contribution_amount || 0, penalty_amount: attendanceMap.get(Number(member.id))?.penalty_amount || 0, penalty_reason: attendanceMap.get(Number(member.id))?.penalty_reason || "", notes: attendanceMap.get(Number(member.id))?.notes || "" })) };
  showForm.value = true;
};
const closeForm = () => { showForm.value = false; editingId.value = null; errorMessage.value = ""; };
const load = async () => { loading.value = true; try { const meetingRequest = getMeetings(); const memberRequest = canManage.value ? getMembers() : Promise.resolve({ data: { data: [] } }); const [meetingResponse, memberResponse] = await Promise.all([meetingRequest, memberRequest]); meetings.value = meetingResponse.data?.data || []; members.value = memberResponse.data?.data || []; } catch (error) { errorMessage.value = error.response?.data?.message || "Unable to load meetings."; } finally { loading.value = false; } };
const submit = async () => { saving.value = true; errorMessage.value = ""; try { const payload = { ...form.value, attendance: form.value.attendance.map(({ first_name, last_name, ...entry }) => ({ ...entry, contribution_amount: Number(entry.contribution_amount || 0), penalty_amount: Number(entry.penalty_amount || 0) })) }; editingId.value ? await updateMeeting(editingId.value, payload) : await createMeeting(payload); closeForm(); await load(); } catch (error) { errorMessage.value = error.response?.data?.message || "Unable to save meeting."; } finally { saving.value = false; } };
const remove = async () => { saving.value = true; try { await deleteMeeting(selectedMeeting.value.id); selectedMeeting.value = null; showDelete.value = false; await load(); } catch (error) { errorMessage.value = error.response?.data?.message || "Unable to delete meeting."; } finally { saving.value = false; } };
onMounted(load);
</script>

<template>
  <DashboardLayout page-title="Meetings" page-subtitle="Group meeting records">
    <section class="page-header"><div class="page-header-copy"><p class="page-header-label">Group operations</p><h2>Meetings</h2><p class="page-header-text mb-0">Track recurring meetings, attendance, contributions, agenda items, and decisions.</p></div><button v-if="canManage" class="btn btn-primary" @click="openCreate"><i class="bi bi-calendar-plus me-2"></i>New meeting</button></section>
    <section class="row g-3 mb-4"><div class="col-12 col-sm-4"><article class="info-card"><small class="info-card-label">Meetings held</small><h3 class="info-card-value">{{ completedCount }}</h3><p class="text-muted mb-0">{{ meetings.length }} total records</p></article></div><div class="col-12 col-sm-4"><article class="info-card"><small class="info-card-label">Average attendance</small><h3 class="info-card-value">{{ averageAttendance }}%</h3><p class="text-muted mb-0">Present and late attendees</p></article></div><div class="col-12 col-sm-4"><article class="info-card"><small class="info-card-label">Contributions collected</small><h3 class="info-card-value">{{ currency(totalContributions) }}</h3><p class="text-muted mb-0">Across recorded meetings</p></article></div></section>
    <div v-if="errorMessage && !showForm" class="alert alert-warning">{{ errorMessage }}</div>
    <section class="meetings-layout"><div class="meeting-list"><div v-if="loading" class="empty-state">Loading meetings...</div><div v-else-if="!meetings.length" class="empty-state">No meeting records yet.</div><article v-for="meeting in meetings" v-else :key="meeting.id" class="meeting-card" :class="{ selected: selectedMeeting?.id === meeting.id }" @click="selectedMeeting=meeting"><div class="meeting-date"><strong>{{ new Date(meeting.meeting_date).getDate() }}</strong><span>{{ new Date(meeting.meeting_date).toLocaleDateString(undefined,{month:'short'}) }}</span></div><div class="meeting-copy"><div><span class="meeting-status" :class="meeting.status">{{ meeting.status }}</span><small>{{ new Date(meeting.meeting_date).toLocaleString() }}</small></div><h3>{{ meeting.agenda }}</h3><div class="meeting-metrics"><span><i class="bi bi-people"></i>{{ Number(meeting.present_count)+Number(meeting.late_count) }} attended</span><span><i class="bi bi-person-x"></i>{{ meeting.absent_count }} absent</span><span><i class="bi bi-cash"></i>{{ currency(meeting.contributions_collected) }}</span></div></div><i class="bi bi-chevron-right"></i></article></div>
      <aside class="meeting-detail card panel-card"><div v-if="!selectedMeeting" class="detail-placeholder"><i class="bi bi-calendar3"></i><span>Select a meeting to see its record.</span></div><template v-else><div class="detail-head"><div><span class="page-header-label">Meeting record</span><h3>{{ new Date(selectedMeeting.meeting_date).toLocaleDateString(undefined,{dateStyle:'long'}) }}</h3></div><div v-if="canManage" class="detail-actions"><button @click="openEdit(selectedMeeting)"><i class="bi bi-pencil"></i></button><button class="danger" @click="showDelete=true"><i class="bi bi-trash"></i></button></div></div><section><h4>Agenda</h4><p>{{ selectedMeeting.agenda }}</p></section><section><h4>Decisions</h4><p>{{ selectedMeeting.decisions || 'No decisions recorded.' }}</p></section><section><h4>Attendance</h4><div class="attendance-list"><div v-for="entry in selectedMeeting.attendance" :key="entry.id"><span class="member-avatar">{{ entry.first_name[0] }}{{ entry.last_name[0] }}</span><div><strong>{{ entry.first_name }} {{ entry.last_name }}</strong><small>{{ currency(entry.contribution_amount) }} contributed</small></div><span class="attendance-status" :class="entry.attendance_status">{{ entry.attendance_status }}</span></div></div></section></template></aside>
    </section>
    <div v-if="showForm" class="modal-backdrop"><div class="modal-panel meeting-modal"><div class="modal-panel-header"><div><p class="page-header-label mb-2">{{ editingId ? 'Edit meeting' : 'New meeting' }}</p><h5 class="mb-0">{{ editingId ? 'Update meeting record' : 'Create meeting record' }}</h5></div><button class="btn btn-close" @click="closeForm"></button></div><form class="mt-3" @submit.prevent="submit"><div class="row g-3"><div class="col-12 col-md-7"><label class="form-label">Meeting date and time</label><input v-model="form.meeting_date" class="form-control" type="datetime-local" required /></div><div class="col-12 col-md-5"><label class="form-label">Status</label><select v-model="form.status" class="form-select"><option value="scheduled">Scheduled</option><option value="completed">Completed</option><option value="cancelled">Cancelled</option></select></div><div class="col-12"><label class="form-label">Agenda</label><textarea v-model="form.agenda" class="form-control" rows="3" required></textarea></div><div class="col-12"><label class="form-label">Decisions</label><textarea v-model="form.decisions" class="form-control" rows="3" placeholder="Record resolutions and action items"></textarea></div></div><div class="attendance-head"><div><strong>Attendance & contributions</strong><span>Every member is included.</span></div><div><span>{{ attendanceSummary.present }} present</span><span>{{ attendanceSummary.absent }} absent</span><strong>{{ currency(attendanceSummary.contributions) }} collected</strong><strong>{{ currency(attendanceSummary.penalties) }} penalties</strong></div></div><div class="attendance-editor"><div v-for="entry in form.attendance" :key="entry.member_id" class="attendance-row"><div><strong>{{ entry.first_name }} {{ entry.last_name }}</strong><small>Member #{{ entry.member_id }}</small></div><select v-model="entry.attendance_status" class="form-select"><option value="present">Present</option><option value="late">Late</option><option value="absent">Absent</option><option value="excused">Excused</option></select><input v-model="entry.contribution_amount" class="form-control" type="number" min="0" placeholder="Contribution" aria-label="Contribution amount" /><input v-model="entry.penalty_amount" class="form-control" type="number" min="0" placeholder="Penalty" aria-label="Penalty amount" /><input v-if="Number(entry.penalty_amount) > 0" v-model="entry.penalty_reason" class="form-control reason-input" placeholder="Penalty reason" aria-label="Penalty reason" /></div></div><p v-if="errorMessage" class="text-danger small mt-3">{{ errorMessage }}</p><div class="modal-actions"><button type="button" class="btn btn-outline-secondary" @click="closeForm">Cancel</button><button class="btn btn-primary" :disabled="saving">{{ saving ? 'Saving...' : 'Save meeting' }}</button></div></form></div></div>
    <div v-if="showDelete" class="modal-backdrop"><div class="modal-panel confirm-panel"><h5>Delete this meeting?</h5><p class="text-muted">The meeting and its attendance record will be removed.</p><div class="modal-actions"><button class="btn btn-outline-secondary" @click="showDelete=false">Cancel</button><button class="btn btn-danger" :disabled="saving" @click="remove">Delete meeting</button></div></div></div>
  </DashboardLayout>
</template>

<style scoped>
.meetings-layout{display:grid;gap:1rem}.meeting-list{display:grid;gap:.65rem;align-content:start}.meeting-card{display:grid;grid-template-columns:auto minmax(0,1fr) auto;align-items:center;gap:.85rem;padding:.85rem;border:1px solid #ececf1;border-radius:11px;background:#fff;cursor:pointer}.meeting-card.selected{border-color:#cfc4ff;box-shadow:0 0 0 2px #f0edff}.meeting-date{width:2.8rem;height:3rem;display:grid;place-items:center;border-radius:9px;background:#f0edff;color:#7056dc}.meeting-date strong{font-size:1rem}.meeting-date span{margin-top:-.5rem;font-size:.6rem;text-transform:uppercase}.meeting-copy{min-width:0}.meeting-copy>div:first-child{display:flex;align-items:center;gap:.5rem}.meeting-copy small{color:#92919a;font-size:.63rem}.meeting-copy h3{margin:.35rem 0;font-size:.82rem;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.meeting-status,.attendance-status{display:inline-flex;padding:.25rem .5rem;border-radius:999px;font-size:.61rem;text-transform:capitalize}.meeting-status.completed,.attendance-status.present{background:#eaf9f1;color:#168657}.meeting-status.scheduled,.attendance-status.excused{background:#f0edff;color:#7056dc}.meeting-status.cancelled,.attendance-status.absent{background:#fff0f1;color:#cf4b58}.attendance-status.late{background:#fff5dd;color:#a66a08}.meeting-metrics{display:flex;flex-wrap:wrap;gap:.65rem;color:#777680;font-size:.64rem}.meeting-detail{padding:1rem}.detail-placeholder{min-height:300px;display:grid;place-items:center;align-content:center;gap:.6rem;color:#92919a;font-size:.75rem}.detail-placeholder i{font-size:1.5rem}.detail-head{display:flex;justify-content:space-between;gap:1rem}.detail-head h3{margin:.2rem 0;font-size:1rem}.detail-actions{display:flex;gap:.35rem}.detail-actions button{width:2rem;height:2rem;border:1px solid #e5e4ea;border-radius:7px;background:#fff;color:#7056dc}.detail-actions .danger{color:#cf4b58}.meeting-detail section{padding:1rem 0;border-top:1px solid #f0f0f3}.meeting-detail h4{font-size:.72rem}.meeting-detail p{margin:0;color:#6e6d75;font-size:.73rem;white-space:pre-wrap}.attendance-list>div{display:grid;grid-template-columns:auto 1fr auto;align-items:center;gap:.55rem;padding:.55rem 0;border-bottom:1px solid #f3f3f5}.member-avatar{width:1.8rem;height:1.8rem;display:grid;place-items:center;border-radius:50%;background:#f0edff;color:#7056dc;font-size:.62rem;font-weight:700}.attendance-list strong,.attendance-list small{display:block;font-size:.68rem}.attendance-list small{color:#93929a}.meeting-modal{width:min(100%,720px)}.attendance-head{display:flex;align-items:flex-end;justify-content:space-between;gap:1rem;margin:1.2rem 0 .6rem}.attendance-head strong,.attendance-head span{display:block}.attendance-head>div:first-child strong{font-size:.78rem}.attendance-head>div:first-child span{color:#92919a;font-size:.65rem}.attendance-head>div:last-child{display:flex;gap:.6rem;font-size:.63rem;text-align:right}.attendance-editor{display:grid;gap:.4rem;max-height:270px;overflow-y:auto;padding-right:.2rem}.attendance-row{display:grid;grid-template-columns:minmax(120px,1fr);gap:.45rem;padding:.65rem;border:1px solid #eeeeF2;border-radius:8px}.attendance-row strong,.attendance-row small{display:block}.attendance-row strong{font-size:.7rem}.attendance-row small{color:#94939b;font-size:.61rem}.attendance-row .form-control,.attendance-row .form-select{min-height:34px!important}@media(min-width:650px){.attendance-row{grid-template-columns:minmax(150px,1fr) 110px 125px 110px}.attendance-row .reason-input{grid-column:2/-1}}@media(min-width:980px){.meetings-layout{grid-template-columns:minmax(0,1fr) minmax(330px,.72fr)}.meeting-detail{position:sticky;top:86px;max-height:calc(100vh - 110px);overflow-y:auto}}
</style>




